import React, { useState } from 'react';
import ChordDiagram from './ChordDiagram';

function ChordDetail({ chord }) {
  const [selectedVariationIndex, setSelectedVariationIndex] = useState(0);

  // Get variations array, default to empty if not present
  const variations = chord.variations || [];
  const hasVariations = variations.length > 0;

  // Determine which fingering to display: primary if no variations or index 0, else variation
  const displayFret = hasVariations && selectedVariationIndex > 0 
    ? variations[selectedVariationIndex - 1].frets 
    : chord.frets;
  const displayFingers = hasVariations && selectedVariationIndex > 0 
    ? variations[selectedVariationIndex - 1].fingers 
    : chord.fingers;

  // Label for the variation
  const variationLabel = hasVariations && selectedVariationIndex > 0 
    ? variations[selectedVariationIndex - 1].label || `Variation ${selectedVariationIndex}` 
    : 'Primary';

  const allVariations = [
    { frets: chord.frets, fingers: chord.fingers, label: 'Primary' },
    ...variations
  ];

  return (
    <div className="chord-detail">
      <h3>{chord.name}</h3>
      <div className="variations-grid">
        {allVariations.map((v, i) => (
          <div key={i} className="variation-item">
            <ChordDiagram 
              frets={v.frets} 
              fingers={v.fingers} 
              size={100} 
              className="chord-detail-diagram"
            />
            <p>{v.label}</p>
          </div>
        ))}
      </div>
    </div>
  );
}


export default ChordDetail;
